function evaluateTabICL()
% Load and display the evaluation generated by trainTabICL.py.
here = fileparts(mfilename('fullpath'));
f = fullfile(here, 'Results', 'EvaluationResults_TabICL.mat');
assert(isfile(f), 'Evaluation file not found. Run trainTabICL.py first.');
R = load(f);
fprintf('TabICLv2 Evaluation\n');
fprintf('Accuracy:          %.2f%%\n', R.accuracy*100);
fprintf('Macro precision:   %.4f\n', R.macroPrecision);
fprintf('Macro recall:      %.4f\n', R.macroRecall);
fprintf('Macro F1:           %.4f\n', R.macroF1);
fprintf('Weighted F1:        %.4f\n', R.weightedF1);
fprintf('Fit/context time:   %.2f seconds\n', R.fitTime);
fprintf('Prediction time:    %.2f seconds\n', R.predictionTime);
end
